/** Optional maintainer tool. The deployed site needs no Node or build step. */
import { createRequire } from 'node:module';
import { readFile, writeFile, mkdir } from 'node:fs/promises';
import { dirname, join, resolve, relative } from 'node:path';
import { fileURLToPath } from 'node:url';
import { createHash } from 'node:crypto';

const here = dirname(fileURLToPath(import.meta.url));
const deps = process.env.INSIGHT_VENDOR_DEPS || here;
const require = createRequire(join(deps, 'package.json'));
const { build } = require('esbuild');
const sdk = JSON.parse(await readFile(join(deps, 'node_modules/@supabase/supabase-js/package.json'), 'utf8'));
if (sdk.version !== '2.118.0') throw new Error('This build requires @supabase/supabase-js 2.118.0.');
const outputDir = resolve(here, '../../vendor');
await mkdir(outputDir, { recursive: true });
const output = join(outputDir, 'supabase-2.118.0.min.js');
const result = await build({
  stdin: { contents: "export { createClient } from '@supabase/supabase-js';", resolveDir: deps, sourcefile: 'insight-supabase-entry.js' },
  absWorkingDir: deps, outfile: output,
  bundle: true, minify: true, format: 'esm', platform: 'browser', target: 'es2020',
  metafile: true, legalComments: 'eof',
  banner: { js: '/* Insight Space: Supabase JS 2.118.0. See THIRD_PARTY_NOTICES.md. */' },
});
const packages = new Set();
for (const file of Object.keys(result.metafile.inputs)) {
  const parts = file.replaceAll('\\', '/').split('node_modules/').pop().split('/');
  if (!file.includes('node_modules/')) continue;
  packages.add(parts[0].startsWith('@') ? parts.slice(0, 2).join('/') : parts[0]);
}
const notices = ['# Bundled third-party software', '', 'Generated by tools/vendor/build.mjs. Only the Supabase client is bundled; application data and credentials are excluded.', ''];
const versions = {};
for (const name of [...packages].sort()) {
  const dir = join(deps, 'node_modules', name);
  const metadata = JSON.parse(await readFile(join(dir, 'package.json'), 'utf8'));
  versions[name] = metadata.version;
  let license = '';
  for (const filename of ['LICENSE', 'LICENSE.md', 'LICENSE.txt', 'license', 'license.md', 'license.txt']) {
    try { license = await readFile(join(dir, filename), 'utf8'); break; } catch { /* try the next spelling */ }
  }
  if (!license) throw new Error('License text not found for ' + name);
  notices.push('## ' + name + ' ' + metadata.version, '', 'License: ' + (metadata.license || 'see text below'), '', license.replaceAll('\r\n', '\n').trim(), '');
}
await writeFile(join(outputDir, 'THIRD_PARTY_NOTICES.md'), notices.join('\n'));
const bytes = await readFile(output);
await writeFile(join(outputDir, 'manifest.json'), JSON.stringify({
  entry: 'supabase-2.118.0.min.js',
  bytes: bytes.length,
  sha256: createHash('sha256').update(bytes).digest('hex'),
  packages: versions,
}, null, 2) + '\n');
console.log('Built ' + relative(process.cwd(), output) + ' (' + bytes.length + ' bytes)');
